#!/bin/sh
# Writes the Homebrew formula of a release to stdout.
#
#   scripts/homebrew/formula.sh VERSION DIST_DIR
#
# DIST_DIR holds the release archives codeweft_VERSION_<os>_<arch>.tar.gz.
set -eu
version="${1#v}"
dist="$2"
repo="${GITHUB_REPOSITORY:-anjanikumarjangid/codeweft}"
sum() { sha256sum "$dist/codeweft_${version}_$1.tar.gz" | cut -d' ' -f1; }
url() { echo "https://github.com/${repo}/releases/download/v${version}/codeweft_${version}_$1.tar.gz"; }
cat <<RUBY
# Generated by scripts/homebrew/formula.sh for codeweft ${version}.
class Codeweft < Formula
  desc "MCP server giving AI coding agents structured context about code and services"
  homepage "https://github.com/${repo}"
  version "${version}"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$(url darwin_arm64)"
      sha256 "$(sum darwin_arm64)"
    end
    on_intel do
      url "$(url darwin_amd64)"
      sha256 "$(sum darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "$(url linux_arm64)"
      sha256 "$(sum linux_arm64)"
    end
    on_intel do
      url "$(url linux_amd64)"
      sha256 "$(sum linux_amd64)"
    end
  end

  def install
    bin.install "codeweft"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/codeweft version")
    (testpath/"main.go").write "package main\\n\\n// Hello greets.\\nfunc Hello() {}\\n\\nfunc main() { Hello() }\\n"
    system bin/"codeweft", "index", "--db", testpath/"index.db", testpath
    assert_match "main.Hello", shell_output("#{bin}/codeweft query --db #{testpath}/index.db hello")
  end
end
RUBY
